// Compared by value so the effect below only re-runs when the bounds actually change
const minimumTimeKey = minimumTime && JSON.stringify(minimumTime);
const maximumTimeKey = maximumTime && JSON.stringify(maximumTime);

const validateCurrentTime = useEffectEvent(() => validate(time));
const validateTime = useEffectEvent((value: Time) => validate(value));

useEffect(() => {
  if (minimumTimeKey || maximumTimeKey) {
    validateCurrentTime();
  }
}, [minimumTimeKey, maximumTimeKey]);

useEffect(() => {
  if (defaultTime) {
    setTime(defaultTime);
    validateTime(defaultTime);
  }
}, [defaultTime]);
